using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Analysis;

internal sealed class OriginalSmoothFieldsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Smooth charged-field smearing on the literal positive-lattice Hilbert completion.",
        H("Original lattice Hilbert space and smooth fields"),
        Blocks(
            Paragraph(Text("The input is the original lattice D with positive definite real Gram matrix and a complex inverse H satisfying both H*gramComplex(D)=1 and gramComplex(D)*H=1. Carrier(D) is the original finite charge sum of oscillator polynomials. Its Hermitian form Hm retains the mixed original colour metric. OriginalCurrentEnergy proves positivity through an invertible real full frame and its genuine FactorialFockMetric identification. No assertion that the original monomials are orthogonal is used.")),
            Paragraph(Text("Write T=1+sugawaraMode(D,H,0). The finite space of Sobolev order k has inner product Hm(T^k u,T^k v) and norm sqrt(Re Hm(T^k v,T^k v)). Its Hilbert completion is H_k; H_0 is the canonical completion of the original Hm norm. The embedding is injective and dense, and its k=0 inner product is exactly Hm. On an original grade E, T^k is multiplication by (E+1)^k. The actual finite-dimensional grade embeds as a closed subspace, so its orthogonal projection has algebraic image. Finite energy truncations converge in every H_k. The inclusions H_k into H_j for j<=k agree with the original identity and are injective and compatible.")),
            Paragraph(Text("For a charge a, d_a=chargeEnergy(D,a)>=0 and q_a=2*d_a. The literal circle mode is A_m^a=actualField(D,a)[[m+d_a-1]]. The existing charged bound chooses C_a>0 before every integer m and every finite mixed input. Different surviving input grades E map to distinct grades E-m, and negative output grades vanish. Orthogonal squared-norm recombination, followed by E-m+1<=(1+abs(m))*(E+1), proves the Sobolev bound of order q_a+k. This is a proof about the actual orthogonal images, rather than an inference from a scalar inequality for arbitrary operators. At a=0 the field is the identity field and only m=0 survives, including the entire rank-zero case.")),
            Paragraph(Text("A test is a globally smooth function on the real line with period 2*pi. Its coefficients agree exactly with fourierCoeff on AddCircle for that period and the convention integral f(theta)*exp(-i*m*theta)/(2*pi). Global periodicity and uniqueness of derivatives give periodicity of every derivative. Iterating Mathlib's fourierCoeffOn_of_hasDerivAt cancels all derivative endpoint terms. The zero mode is bounded separately. For every integer r>=0 the two-sided weighted sum W_r(f)=sum_m abs(fhat(m))*(1+abs(m))^r is finite. One finite bound is the supremum norm of f plus 2^r times the supremum norm of derivative r+2 times sum over nonzero integers of 1/m^2. No decay predicate or finite Fourier support is assumed.")),
            Describe.Lean(
                DescribeId.Create("original-smooth-fields-infinite-smearing"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Analysis/OriginalSmoothFields.original_smooth_fields"),
                H("Infinite smooth charged fields and their minimal closures"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every original positive Model and every charge a there is C_a>0, fixed before the smooth periodic test f, such that for every f and every k>=0 the series sum over all integers of fhat(m)*A_m^a converges absolutely in B(H_(q_a+k),H_k), with norm bounded by C_a*W_(q_a+k)(f). The resulting maps agree under the Sobolev inclusions. On the dense intersection H_infinity they define an invariant linear field A^a(f) satisfying norm_k(A^a(f)v)<=C_a*W_(q_a+k)(f)*norm_(q_a+k)(v). The domain contains the original finite carrier. The smeared image can have infinite energy support; no invariance of the finite carrier is asserted.")),
                    Paragraph(Text("The same actual charge sectors, closed in the Hilbert completion, are transported from delta to a+delta. Closed finite-dimensional intersections of charge sectors and grades identify sector membership at every Sobolev order. Original finite energy truncations approximate both a smooth vector and its smeared image in the Hilbert graph norm. Consequently the closure of the restriction to finite carrier inputs equals the closure of the field on H_infinity, and the finite input carrier is a core for this minimal closure.")),
                    Paragraph(Text("The original opposite-charge mode identity extends first by dense Sobolev pairing limits and then by absolute sums. With the inner product conjugate linear in the first slot, conjugate(fhat(-n)) is the n-th coefficient of the pointwise conjugate test. Thus inner(A^a(f)u,v)=inner(u,eta_a*A^(-a)(conjugate(f))v), where eta_a=paritySign(d_a)=epsilon(D,a,-a). The phase stays in the second slot. Both operators have the same explicit dense domain. Mathlib's formal-adjoint inclusion and closedness of adjoints provide closed extensions and prove closability of both operators. Mathlib's existing closure and core machinery supplies the stated minimal closure and core."))),
                DescribeRole.Theorem),
            Paragraph(Text("The mathematical construction follows the smooth-smearing interpretation of polynomial energy bounds in Carpi and Tomassini, arXiv:2303.14097v2. Original lattice and source-pairing attributions remain with the Bakalov-Kac and related suppliers. Completion, Fourier integration by parts, finite-dimensional closedness and partial-operator adjoints use Mathlib; no literature novelty is claimed. Mutual adjoint-closure equality, essential self-adjointness, strong locality and strong commutation remain separate problems. The abstract Jacobi countermodel to an implication from energy/shift/domain data is not a counterexample to the literal lattice VOA. All-state field extension, BRST/no-ghost and the physical string-theory/AdS-CFT objectives require additional results."))),
        []));
}
